export function Tag({
  label = "{{label}}",
  variant = "{{variant}}",
  color = "{{color}}",
  removable = {{removable}},
}) {
  const palette = variant === "solid"
    ? { background: color, color: "#241430", borderColor: color }
    : { background: "transparent", color, borderColor: color };
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontWeight: 600, fontSize: 11.5,
      padding: "3px 8px", borderRadius: 4, boxSizing: "border-box", border: "1.5px solid", lineHeight: 1.4, ...palette }}>
      {label}
      {removable && (
        <button type="button" aria-label={`Remove ${label} tag`} style={{ border: "none", background: "transparent",
          color: "inherit", fontSize: 12, lineHeight: 1, cursor: "pointer", padding: 0, opacity: 0.7 }}>×</button>
      )}
    </span>
  );
}
